// `wasm/` is generated by `npm run wasm` (crates/musette-wasm, git-ignored).
import type * as Wasm from './wasm/musette_wasm';
import type {
  Capabilities,
  Core,
  DeviceActivity,
  DeviceField,
  DeviceSetting,
  Outcome,
  ParsedRoute,
  RouteAnalysis,
  Step,
} from './types';

const f64 = (a: number[]) => Float64Array.from(a);

/** serde-wasm-bindgen gives byte vectors as arrays and `None` as undefined or null. */
type Raw = Record<string, unknown>;
const opt = <T>(v: unknown): T | undefined => (v ?? undefined) as T | undefined;

function outcome(o: Raw): Outcome {
  switch (o.kind) {
    case 'file':
      return { kind: 'file', bytes: Uint8Array.from(o.bytes as number[]) };
    case 'activities':
      return {
        kind: 'activities',
        activities: (o.activities as Raw[]).map(
          (a): DeviceActivity => ({
            id: a.id as string,
            startTime: opt(a.startTime),
            localTime: a.localTime as boolean,
            size: opt(a.size),
            synced: opt(a.synced),
          }),
        ),
      };
    case 'settings':
      return {
        kind: 'settings',
        fields: (o.fields as Raw[]).map(field),
        values: (o.values as Raw[]).map(
          (v): DeviceSetting => ({ key: v.key as string, number: opt(v.number), text: v.text as string }),
        ),
      };
    default:
      return o as unknown as Outcome;
  }
}

const field = (f: Raw): DeviceField => ({ ...(f as unknown as DeviceField), min: opt(f.min), max: opt(f.max) });

function step(s: Raw): Step {
  return {
    subscribe: s.subscribe as number[],
    writes: (s.writes as Raw[]).map((w) => ({ channel: w.channel as number, bytes: Uint8Array.from(w.bytes as number[]) })),
    progress: opt(s.progress),
    waitMs: opt(s.waitMs),
    outcome: s.outcome ? outcome(s.outcome as Raw) : undefined,
  };
}

/** The Core over the WASM build of musette-core, once initialised. */
export function wasmCore(m: typeof Wasm): Core {
  return {
    analyzeRoute: (lats, lons, eles) => m.analyzeRoute(f64(lats), f64(lons), f64(eles)) as RouteAnalysis,
    parseGpx(text) {
      const r = m.parseGpx(text) as { name: string; lats: Float64Array; lons: Float64Array; eles: Float64Array };
      return { name: r.name, lats: [...r.lats], lons: [...r.lons], eles: [...r.eles] } satisfies ParsedRoute;
    },
    verifyFit: (bytes) => m.verifyFit(bytes),
    brytonFindActivities: (paths, sizes) =>
      (m.brytonFindActivities(paths, f64(sizes)) as { id: string; size?: number | null }[]).map((a) => ({
        id: a.id,
        size: a.size ?? undefined,
      })),
    capabilities: (model, link) => m.capabilities(model, link) as Capabilities,
    settingFields: (model) => (m.settingFields(model) as Raw[]).map(field),
    session(model, timing) {
      const s = new m.Session(model, timing?.requestMs, timing?.shortMs);
      return {
        channels: () => s.channels(),
        connect: () => step(s.connect()),
        listActivities: () => step(s.listActivities()),
        download: (id, size) => step(s.download(id, size)),
        acknowledge: (id) => step(s.acknowledge(id)),
        sendRoute: (r) => step(s.sendRoute(r.name, f64(r.lats), f64(r.lons), f64(r.eles))),
        sendFile: (kind, bytes) => step(s.sendFile(kind, bytes)),
        readSettings: () => step(s.readSettings()),
        writeSettings: (changes) =>
          step(
            s.writeSettings(
              changes.map((c) => c.key),
              f64(changes.map((c) => c.number ?? NaN)),
              changes.map((c) => c.text),
            ),
          ),
        onNotify: (channel, bytes) => step(s.onNotify(channel, bytes)),
        onTimeout: () => step(s.onTimeout()),
        free: () => s.free(),
      };
    },
    cc600Simulator(o = {}) {
      const d = new m.Cc600Simulator(
        o.window ?? 0,
        o.free ?? 0,
        o.settings ?? '',
        Uint32Array.from(o.loseChunks ?? []),
        Uint32Array.from(o.loseAcks ?? []),
      );
      return {
        addActivity: (id, startTime, fit) => d.addActivity(id, startTime, fit),
        write: (bytes) => d.write(bytes) as Uint8Array[],
        disconnect: () => d.disconnect(),
        received: () => d.received(),
        committed: () => d.committed() ?? undefined,
        chunkBytes: () => d.chunkBytes(),
        acked: () => [...d.acked()],
        settings: () => d.settings(),
        settingsWrites: () => d.settingsWrites(),
      };
    },
  };
}
